/**
 * Asset manifest loader (CNT-FR-05, CNT-FR-06, VIS-CON-06, VIS-NFR-02).
 *
 * `public/assets/assets.manifest.json` is generated by
 * `scripts/generate-placeholder-assets.mjs` and is the only mapping from a
 * content id to an SVG file. This module re-exports that manifest with engine
 * element types and resolves a manifest path against a caller-supplied base URL.
 *
 * The loader is pure and synchronous:
 *  - it never reads `import.meta.env`, `window`, `document` or storage; the
 *    caller passes `import.meta.env.BASE_URL`;
 *  - an unknown id returns `undefined` instead of throwing, so the UI can render
 *    a labelled fallback;
 *  - it concatenates the normalized base, `assets/` and the manifest path. It
 *    never hands a leading-slash path to `new URL`, which would escape a GitHub
 *    Pages project subpath (VIS-CON-02).
 *
 * Consumers must not import an SVG directly through Vite: every image goes
 * through `resolveAsset`, which is what makes replacing a file at its manifest
 * path a no-code change.
 */
import manifestJson from '../../public/assets/assets.manifest.json';
import type { Element } from '../engine/types';

export const ASSET_KINDS = ['card', 'enemy', 'field'] as const;
export type AssetKind = (typeof ASSET_KINDS)[number];

/**
 * One class-wide spec block. Card carries the extra band metadata the battle
 * board uses to reserve vertical space before the SVG decodes; enemy and field
 * only need a canvas and a safe-area inset.
 */
export interface AssetSpec {
  readonly width: number;
  readonly height: number;
  readonly format: 'svg';
  /** Inset in pixels that text, glyphs and badges must stay inside. */
  readonly safeArea: number;
  readonly titleBand?: number;
  readonly artBox?: readonly [width: number, height: number];
  readonly textBand?: number;
}

export type AssetSpecs = Readonly<Record<AssetKind, AssetSpec>>;

/**
 * One manifest entry. `id` is namespaced (`card:`, `enemy:`, `field:`) and
 * `path` is relative to `public/assets/`, uses forward slashes and never starts
 * with a slash.
 */
export interface AssetEntry {
  readonly id: string;
  readonly kind: AssetKind;
  readonly element: Element;
  /** Display name for alt text and the labelled fallback. */
  readonly name: string;
  readonly path: string;
  readonly width: number;
  readonly height: number;
  readonly format: 'svg';
  readonly safeArea: number;
}

export interface AssetManifest {
  readonly version: number;
  readonly generatedBy: string;
  readonly spec: AssetSpecs;
  readonly assets: readonly AssetEntry[];
}

/**
 * The JSON module widens `format` and `element` to `string`; the manifest test
 * proves every entry against the catalogs and the published spec, so this cast
 * is only the bridge from JSON's inferred shape to the manifest contract.
 */
export const ASSET_MANIFEST: AssetManifest =
  manifestJson as unknown as AssetManifest;

/** Manifest entries in published (id-sorted) order. */
export const ASSETS: readonly AssetEntry[] = ASSET_MANIFEST.assets;

/** Every manifest id, in published order. */
export const ASSET_IDS: readonly string[] = ASSETS.map((entry) => entry.id);

/**
 * Id lookup. A frozen, prototype-less record so consumers can index it directly
 * and an unknown id - including names such as `toString` - yields `undefined`
 * rather than an inherited function.
 */
export const byId: Readonly<Record<string, AssetEntry>> = Object.freeze(
  ASSETS.reduce<Record<string, AssetEntry>>((entries, entry) => {
    entries[entry.id] = entry;
    return entries;
  }, Object.create(null) as Record<string, AssetEntry>),
);

/**
 * Typed lookup with an explicit signature. `Object.hasOwn` guards the prototype
 * chain, so ids such as `constructor` or `toString` return `undefined` rather
 * than an inherited function.
 */
export function assetById(id: string): AssetEntry | undefined {
  return Object.hasOwn(byId, id) ? byId[id] : undefined;
}

/**
 * Returns a base URL that ends with exactly one forward slash.
 * `'/'`, `''` -> `'/'`; `'/Card-Game-Project'` -> `'/Card-Game-Project/'`.
 */
export function normalizeBase(baseUrl: string): string {
  const trimmed = baseUrl.replace(/\/+$/, '');
  return trimmed === '' ? '/' : `${trimmed}/`;
}

/**
 * Resolves a known manifest id to `base + assets/ + path`.
 *
 * `resolveAsset('card:ember-cinder-jab', '/Card-Game-Project/')` returns
 * `'/Card-Game-Project/assets/cards/ember-cinder-jab.svg'`.
 * Unknown ids return `undefined` and are never an exception.
 */
export function resolveAsset(id: string, baseUrl: string): string | undefined {
  const entry = assetById(id);

  if (entry === undefined) {
    return undefined;
  }

  return `${normalizeBase(baseUrl)}assets/${entry.path}`;
}
